package com.trainflow.trainingneed; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_needs") public class TrainingNeed {
 @Id @JdbcTypeCode(SqlTypes.VARCHAR) @Column(columnDefinition="char(36)") private UUID id; @JdbcTypeCode(SqlTypes.VARCHAR) @Column(name="training_case_id",nullable=false,unique=true,columnDefinition="char(36)") private UUID trainingCaseId;
 @Column(name="target_audience",length=500) private String targetAudience; @Enumerated(EnumType.STRING) @Column(length=20) private TrainingNeedLevel level; @Column(length=300) private String location; @Column(name="participant_count") private Integer participantCount; @Enumerated(EnumType.STRING) @Column(name="delivery_mode",length=20) private DeliveryMode deliveryMode; @Column(name="duration_hours",precision=8,scale=2) private BigDecimal durationHours; @Column(name="planned_days_count") private Integer plannedDaysCount; @Column(columnDefinition="text") private String objectives; @Column(name="desired_start_date") private LocalDate desiredStartDate; @Column(name="desired_end_date") private LocalDate desiredEndDate; @Column(columnDefinition="text") private String constraints; @Column(name="is_validated",nullable=false) private boolean validated; @Column(name="validated_at") private Instant validatedAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected TrainingNeed(){} public TrainingNeed(UUID caseId){id=UUID.randomUUID();trainingCaseId=caseId;} @PrePersist void insert(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();}
 public UUID getId(){return id;} public UUID getTrainingCaseId(){return trainingCaseId;} public String getTargetAudience(){return targetAudience;} public void setTargetAudience(String v){targetAudience=v;} public TrainingNeedLevel getLevel(){return level;} public void setLevel(TrainingNeedLevel v){level=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public Integer getParticipantCount(){return participantCount;} public void setParticipantCount(Integer v){participantCount=v;} public DeliveryMode getDeliveryMode(){return deliveryMode;} public void setDeliveryMode(DeliveryMode v){deliveryMode=v;} public BigDecimal getDurationHours(){return durationHours;} public void setDurationHours(BigDecimal v){durationHours=v;} public Integer getPlannedDaysCount(){return plannedDaysCount;} public void setPlannedDaysCount(Integer v){plannedDaysCount=v;} public String getObjectives(){return objectives;} public void setObjectives(String v){objectives=v;} public LocalDate getDesiredStartDate(){return desiredStartDate;} public void setDesiredStartDate(LocalDate v){desiredStartDate=v;} public LocalDate getDesiredEndDate(){return desiredEndDate;} public void setDesiredEndDate(LocalDate v){desiredEndDate=v;} public String getConstraints(){return constraints;} public void setConstraints(String v){constraints=v;} public boolean isValidated(){return validated;} public void setValidated(boolean v){validated=v;} public Instant getValidatedAt(){return validatedAt;} public void setValidatedAt(Instant v){validatedAt=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}
